<!--
 * 消息路由规则表单组件
 *
 * @path apps/message-web/src/views/route-rule/route-rule-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：路由规则新增/编辑表单（RouteRuleUpsertDTO）提交 create/update。
-->
<script lang="ts" setup>
/**
 * 消息路由（表单组件）
 * <p>消费后端契约 RouteRuleController#create/update（src/api/route-rule.ts，auto-generated by bash/gen-contract.py）：
 * 按 RouteRuleUpsertDTO 字段（ruleCode/ruleName/bizType/channel/priority/conditionExpr/targetChannel/
 * fallbackChannel/status/description/sortOrder 等）填写，新增调 create()、编辑调 update({id}, data)，
 * 成功后 emit('success') 并关闭弹窗。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYDSZModal } from '@ydsz/common-ui';
import {
  ElForm,
  ElFormItem,
  ElInput,
  ElInputNumber,
  ElMessage,
  ElRadio,
  ElRadioGroup,
} from 'element-plus';
import { computed, reactive, ref } from 'vue';

import { create, update } from '#/api/routeRule';
import type { MsgRouteRuleVO } from '#/api/models';

const emit = defineEmits<{ success: [] }>();

const formRef = ref();
const isEdit = ref(false);

/** 路由规则表单状态（字段对应 RouteRuleUpsertDTO） */
interface RouteRuleFormState {
  id: string;
  ruleCode: string;
  ruleName: string;
  bizType: string;
  channel: string;
  priority: number;
  conditionExpr: string;
  targetChannel: string;
  fallbackChannel: string;
  status: string;
  description: string;
  sortOrder: number;
}

const formData = reactive<RouteRuleFormState>({
  id: '',
  ruleCode: '',
  ruleName: '',
  bizType: '',
  channel: '',
  priority: 0,
  conditionExpr: '',
  targetChannel: '',
  fallbackChannel: '',
  status: 'ENABLED',
  description: '',
  sortOrder: 0,
});

const rules = {
  ruleName: [{ required: true, message: '请输入规则名称', trigger: 'blur' }],
  conditionExpr: [{ required: true, message: '请输入条件表达式', trigger: 'blur' }],
  targetChannel: [{ required: true, message: '请输入目标通道', trigger: 'blur' }],
};

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    const data = modalApi.getData<{ record?: MsgRouteRuleVO }>();
    if (data?.record) {
      isEdit.value = true;
      Object.assign(formData, {
        id: data.record.id ?? '',
        ruleCode: data.record.ruleCode ?? '',
        ruleName: data.record.ruleName ?? '',
        bizType: data.record.bizType ?? '',
        channel: data.record.channel ?? '',
        priority: data.record.priority ?? 0,
        conditionExpr: data.record.conditionExpr ?? '',
        targetChannel: data.record.targetChannel ?? '',
        fallbackChannel: data.record.fallbackChannel ?? '',
        status: data.record.status ?? 'ENABLED',
        description: data.record.description ?? '',
        sortOrder: data.record.sortOrder ?? 0,
      });
    } else {
      isEdit.value = false;
      Object.assign(formData, {
        id: '',
        ruleCode: '',
        ruleName: '',
        bizType: '',
        channel: '',
        priority: 0,
        conditionExpr: '',
        targetChannel: '',
        fallbackChannel: '',
        status: 'ENABLED',
        description: '',
        sortOrder: 0,
      });
    }
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      const payload = {
        ruleCode: formData.ruleCode || undefined,
        ruleName: formData.ruleName,
        bizType: formData.bizType || undefined,
        channel: formData.channel || undefined,
        priority: formData.priority,
        conditionExpr: formData.conditionExpr,
        targetChannel: formData.targetChannel,
        fallbackChannel: formData.fallbackChannel || undefined,
        status: formData.status || undefined,
        description: formData.description || undefined,
        sortOrder: formData.sortOrder,
      };
      if (isEdit.value) {
        await update({ id: formData.id }, payload);
        ElMessage.success('更新成功');
      } else {
        await create(payload);
        ElMessage.success('创建成功');
      }
      emit('success');
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});

const title = computed(() => (isEdit.value ? '编辑路由规则' : '新增路由规则'));
</script>
<template>
  <Modal :title="title">
    <ElForm
      ref="formRef"
      :model="formData"
      :rules="rules"
      label-width="100px"
      label-position="right"
    >
      <ElFormItem label="规则名称" prop="ruleName">
        <ElInput v-model="formData.ruleName" placeholder="请输入规则名称" />
      </ElFormItem>
      <ElFormItem label="规则编码" prop="ruleCode">
        <ElInput
          v-model="formData.ruleCode"
          placeholder="请输入规则编码（可为空）"
          :disabled="isEdit"
        />
      </ElFormItem>
      <ElFormItem label="业务类型" prop="bizType">
        <ElInput v-model="formData.bizType" placeholder="请输入业务类型（可为空）" />
      </ElFormItem>
      <ElFormItem label="触发通道" prop="channel">
        <ElInput v-model="formData.channel" placeholder="请输入触发通道（可为空）" />
      </ElFormItem>
      <ElFormItem label="条件表达式" prop="conditionExpr">
        <ElInput
          v-model="formData.conditionExpr"
          type="textarea"
          :rows="2"
          placeholder="请输入条件表达式"
        />
      </ElFormItem>
      <ElFormItem label="目标通道" prop="targetChannel">
        <ElInput v-model="formData.targetChannel" placeholder="请输入目标通道" />
      </ElFormItem>
      <ElFormItem label="兜底通道" prop="fallbackChannel">
        <ElInput v-model="formData.fallbackChannel" placeholder="请输入兜底通道（可为空）" />
      </ElFormItem>
      <ElFormItem label="优先级" prop="priority">
        <ElInputNumber v-model="formData.priority" :min="0" :max="999" />
      </ElFormItem>
      <ElFormItem label="排序" prop="sortOrder">
        <ElInputNumber v-model="formData.sortOrder" :min="0" :max="99999" />
      </ElFormItem>
      <ElFormItem label="状态" prop="status">
        <ElRadioGroup v-model="formData.status">
          <ElRadio value="ENABLED">启用</ElRadio>
          <ElRadio value="DISABLED">禁用</ElRadio>
        </ElRadioGroup>
      </ElFormItem>
      <ElFormItem label="描述" prop="description">
        <ElInput
          v-model="formData.description"
          type="textarea"
          :rows="2"
          placeholder="请输入描述（可为空）"
        />
      </ElFormItem>
    </ElForm>
  </Modal>
</template>
